using UnityEngine;
namespace Fsp.World{public sealed class AirstripRoadLink:MonoBehaviour{void Start(){if(transform.childCount>0)return;Road(new Vector3(105,.05f,92),new Vector3(155,.05f,-120),7);Road(new Vector3(72,.05f,-48),new Vector3(155,.05f,-120),7);}void Road(Vector3 a,Vector3 b,float w){var m=Mat(new Color(.23f,.22f,.20f));var prev=a;for(int i=1;i<=13;i++){float t=i/13f;var p=Vector3.Lerp(a,b,t);p.z+=Mathf.Sin(t*Mathf.PI)*8;var d=p-prev;var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name="AirstripRoad";g.transform.SetParent(transform,false);g.transform.position=(p+prev)*.5f;g.transform.rotation=Quaternion.LookRotation(d.normalized);g.transform.localScale=new Vector3(w,.12f,d.magnitude+.8f);var r=g.GetComponent<Renderer>();if(r!=null)r.sharedMaterial=m;prev=p;}}static Material Mat(Color c){var s=Shader.Find("Standard");var m=new Material(s!=null?s:Shader.Find("Sprites/Default"));m.color=c;return m;}}}
